<!doctype html><html><head><meta charset="utf-8"><style>body{font:11px Arial;color:#102a2a}h1{margin:0}table{width:100%;border-collapse:collapse;margin-top:18px}thead{display:table-header-group}th{background:#d7f3ed;text-align:left}th,td{padding:7px;border-bottom:1px solid #d9e8e5}.amount{text-align:right}.note{color:#4b6864;font-size:9px}</style></head><body><h1>{{ $shop->name }} - Sales Report</h1><p>Generated {{ now()->format('M d, Y g:i A') }} · Net sales: {{ $netSales }} · Net revenue: ₱{{ number_format($netRevenue,2) }}</p><p class="note">Showing the latest {{ $orders->count() }} of {{ $totalOrders }} orders. Download Sales CSV for the complete transaction-level export.</p><table><thead><tr><th>Order</th><th>Date</th><th>Cashier</th><th>Payment</th><th>Status</th><th class="amount">Total</th></tr></thead><tbody>@foreach($orders as $order)<tr><td>#{{ str_pad($order->id,5,'0',STR_PAD_LEFT) }}</td><td>{{ $order->created_at->format('M d, Y') }}</td><td>{{ $order->cashier?->name }}</td><td>{{ ucfirst($order->payment_method) }}</td><td>{{ ucfirst($order->status) }}</td><td class="amount">₱{{ number_format($order->total,2) }}</td></tr>@endforeach</tbody></table></body></html>
